func pairWithSum(_ sorted: [Int], _ target: Int) -> (Int, Int)? {
    var l = 0, r = sorted.count - 1
    while l < r {
        let sum = sorted[l] + sorted[r]
        if sum == target { return (l, r) }
        if sum < target { l += 1 } else { r -= 1 }
    }
    return nil
}

func mergeTwoLists(_ l1: ListNode?, _ l2: ListNode?) -> ListNode? {
    let dummy = ListNode(0)
    var tail = dummy
    var a = l1, b = l2
    while let x = a, let y = b {
        if x.val <= y.val { tail.next = x; a = x.next }
        else { tail.next = y; b = y.next }
        tail = tail.next!
    }
    tail.next = a ?? b
    return dummy.next
}

func isPalindrome(_ s: String) -> Bool {
    let chars = Array(s.lowercased()).filter { $0.isLetter || $0.isNumber }
    var l = 0, r = chars.count - 1
    while l < r {
        if chars[l] != chars[r] { return false }
        l += 1; r -= 1
    }
    return true
}

func maxArea(_ height: [Int]) -> Int {
    var l = 0, r = height.count - 1
    var best = 0
    while l < r {
        let area = (r - l) * min(height[l], height[r])
        best = max(best, area)
        if height[l] < height[r] { l += 1 } else { r -= 1 }
    }
    return best
}

func threeSum(_ nums: [Int]) -> [[Int]] {
    let a = nums.sorted()
    var out: [[Int]] = []
    for i in a.indices {
        if i > 0 && a[i] == a[i - 1] { continue }
        var l = i + 1, r = a.count - 1
        while l < r {
            let sum = a[i] + a[l] + a[r]
            if sum < 0 { l += 1 }
            else if sum > 0 { r -= 1 }
            else {
                out.append([a[i], a[l], a[r]])
                l += 1; r -= 1
                while l < r && a[l] == a[l - 1] { l += 1 }
            }
        }
    }
    return out
}

func removeNthFromEnd(_ head: ListNode?, _ n: Int) -> ListNode? {
    let dummy = ListNode(0, head)
    var lead: ListNode? = dummy, trail: ListNode? = dummy
    for _ in 0..<n { lead = lead?.next }
    while lead?.next != nil {
        lead = lead?.next
        trail = trail?.next
    }
    trail?.next = trail?.next?.next
    return dummy.next
}

func twoSumSorted(_ numbers: [Int], _ target: Int) -> [Int] {
    var l = 0, r = numbers.count - 1
    while l < r {
        let sum = numbers[l] + numbers[r]
        if sum == target { return [l + 1, r + 1] }   // answer is 1-indexed
        if sum < target { l += 1 } else { r -= 1 }
    }
    return []
}

func trap(_ height: [Int]) -> Int {
    var l = 0, r = height.count - 1
    var leftMax = 0, rightMax = 0, water = 0
    while l < r {
        if height[l] < height[r] {
            leftMax = max(leftMax, height[l])
            water += leftMax - height[l]
            l += 1
        } else {
            rightMax = max(rightMax, height[r])
            water += rightMax - height[r]
            r -= 1
        }
    }
    return water
}

func shortestWindow(_ nums: [Int], atLeast target: Int) -> Int {
    var left = 0, sum = 0, best = Int.max
    for right in nums.indices {
        sum += nums[right]                 // grow
        while sum >= target {              // shrink while still valid
            best = min(best, right - left + 1)
            sum -= nums[left]; left += 1
        }
    }
    return best == Int.max ? 0 : best
}

func lengthOfLongestSubstring(_ s: String) -> Int {
    let chars = Array(s)
    var last: [Character: Int] = [:]    // char -> last index seen
    var left = 0, best = 0
    for (right, ch) in chars.enumerated() {
        if let k = last[ch], k >= left { left = k + 1 }
        last[ch] = right
        best = max(best, right - left + 1)
    }
    return best
}

func characterReplacement(_ s: String, _ k: Int) -> Int {
    let chars = Array(s)
    var count: [Character: Int] = [:]
    var left = 0, maxCount = 0, best = 0
    for right in chars.indices {
        count[chars[right], default: 0] += 1
        maxCount = max(maxCount, count[chars[right]]!)
        while (right - left + 1) - maxCount > k {
            count[chars[left]]! -= 1
            left += 1
        }
        best = max(best, right - left + 1)
    }
    return best
}

func minWindow(_ s: String, _ t: String) -> String {
    let chars = Array(s)
    var need: [Character: Int] = [:]
    for ch in t { need[ch, default: 0] += 1 }
    var missing = t.count               // characters of t not yet covered
    var left = 0, bestStart = 0, bestLen = Int.max
    for right in chars.indices {
        if need[chars[right], default: 0] > 0 { missing -= 1 }
        need[chars[right], default: 0] -= 1
        while missing == 0 {
            if right - left + 1 < bestLen {
                bestLen = right - left + 1
                bestStart = left
            }
            need[chars[left]]! += 1
            if need[chars[left]]! > 0 { missing += 1 }
            left += 1
        }
    }
    return bestLen == Int.max ? "" : String(chars[bestStart..<bestStart + bestLen])
}

func hasCycle(_ head: PNode?) -> Bool {
    var slow = head, fast = head
    while let f = fast?.next?.next {
        slow = slow?.next
        fast = f
        if slow === fast { return true }
    }
    return false
}

func hasCycle(_ head: CycleNode?) -> Bool {
    var slow = head, fast = head
    while let next = fast?.next?.next {
        slow = slow?.next
        fast = next
        if slow === fast { return true }
    }
    return false
}

func middleNode(_ head: ListNode?) -> ListNode? {
    var slow = head, fast = head
    while let next = fast?.next {
        slow = slow?.next
        fast = next.next
    }
    return slow
}

func reorderList(_ head: ListNode?) {
    var slow = head, fast = head
    while let next = fast?.next?.next {
        slow = slow?.next
        fast = next
    }
    var prev: ListNode? = nil
    var cur = slow?.next
    slow?.next = nil                    // cut the list in two
    while let node = cur {
        let next = node.next
        node.next = prev
        prev = node
        cur = next
    }
    var first = head, second = prev
    while let a = first, let b = second {
        let an = a.next, bn = b.next
        a.next = b
        b.next = an
        first = an
        second = bn
    }
}

func findDuplicate(_ nums: [Int]) -> Int {
    var slow = nums[0], fast = nums[nums[0]]
    while slow != fast {
        slow = nums[slow]
        fast = nums[nums[fast]]
    }
    slow = 0
    while slow != fast {
        slow = nums[slow]
        fast = nums[fast]
    }
    return slow
}

struct PrefixSum {
    private var pre: [Int] = [0]           // pre[i] = sum of first i items
    init(_ nums: [Int]) { for x in nums { pre.append(pre.last! + x) } }
    func sum(_ lo: Int, _ hi: Int) -> Int { pre[hi + 1] - pre[lo] }  // inclusive
}

struct NumArray {
    private var prefix: [Int] = [0]     // prefix[i] = sum of the first i values
    init(_ nums: [Int]) {
        for x in nums { prefix.append(prefix.last! + x) }
    }
    func sumRange(_ left: Int, _ right: Int) -> Int {
        prefix[right + 1] - prefix[left]
    }
}

func productExceptSelf(_ nums: [Int]) -> [Int] {
    var out = [Int](repeating: 1, count: nums.count)
    var prefix = 1
    for i in nums.indices {
        out[i] = prefix                 // product of everything left of i
        prefix *= nums[i]
    }
    var suffix = 1
    for i in nums.indices.reversed() {
        out[i] *= suffix                // times everything right of i
        suffix *= nums[i]
    }
    return out
}

func subarraySum(_ nums: [Int], _ k: Int) -> Int {
    var count = 0, sum = 0
    var seen: [Int: Int] = [0: 1]       // prefix sum -> times seen
    for x in nums {
        sum += x
        count += seen[sum - k, default: 0]
        seen[sum, default: 0] += 1
    }
    return count
}

func firstDuplicate(_ nums: [Int]) -> Int? {
    var seen = Set<Int>()
    for x in nums where !seen.insert(x).inserted { return x }
    return nil
}

func twoSumBrute(_ nums: [Int], _ target: Int) -> [Int] {
    for i in 0..<nums.count {
        for j in (i + 1)..<nums.count where nums[i] + nums[j] == target {
            return [i, j]
        }
    }
    return []
}

func twoSum(_ nums: [Int], _ target: Int) -> [Int] {
    var seen: [Int: Int] = [:]          // value -> index
    for (i, x) in nums.enumerated() {
        let need = target - x
        if let j = seen[need] { return [j, i] }
        seen[x] = i
    }
    return []
}

func containsDuplicate(_ nums: [Int]) -> Bool {
    var seen = Set<Int>()
    for x in nums {
        if !seen.insert(x).inserted { return true }
    }
    return false
}

func isAnagram(_ s: String, _ t: String) -> Bool {
    var counts: [Character: Int] = [:]
    for ch in s { counts[ch, default: 0] += 1 }
    for ch in t {
        guard let c = counts[ch], c > 0 else { return false }
        counts[ch] = c - 1
    }
    return counts.values.allSatisfy { $0 == 0 }
}

func groupAnagrams(_ strs: [String]) -> [[String]] {
    var groups: [String: [String]] = [:]    // sorted letters -> words
    for word in strs {
        let key = String(word.sorted())
        groups[key, default: []].append(word)
    }
    return Array(groups.values)
}

func longestConsecutive(_ nums: [Int]) -> Int {
    let set = Set(nums)
    var best = 0
    for x in set where !set.contains(x - 1) {    // x starts a run
        var length = 1
        while set.contains(x + length) { length += 1 }
        best = max(best, length)
    }
    return best
}

final class LRUCache {
    private final class Node {
        let key: Int; var value: Int
        weak var prev: Node?
        var next: Node?
        init(_ k: Int, _ v: Int) { key = k; value = v }
    }
    private var map: [Int: Node] = [:]
    private let head = Node(0, 0), tail = Node(0, 0)   // sentinels
    private let capacity: Int
    init(_ capacity: Int) {
        self.capacity = capacity
        head.next = tail; tail.prev = head
    }
    private func unlink(_ n: Node) {
        n.prev?.next = n.next; n.next?.prev = n.prev
    }
    private func pushFront(_ n: Node) {
        n.next = head.next; n.prev = head
        head.next?.prev = n; head.next = n
    }
    func get(_ key: Int) -> Int {
        guard let n = map[key] else { return -1 }
        unlink(n); pushFront(n)          // now the most recently used
        return n.value
    }
    func put(_ key: Int, _ value: Int) {
        if let n = map[key] {
            n.value = value
            unlink(n); pushFront(n)
            return
        }
        if map.count == capacity, let old = tail.prev {
            unlink(old); map[old.key] = nil      // evict the least recently used
        }
        let n = Node(key, value)
        map[key] = n; pushFront(n)
    }
}

func firstIndex(in range: Range<Int>, where ok: (Int) -> Bool) -> Int {
    var lo = range.lowerBound, hi = range.upperBound   // answer in [lo, hi]
    while lo < hi {
        let mid = lo + (hi - lo) / 2
        if ok(mid) { hi = mid } else { lo = mid + 1 }
    }
    return lo                                          // == upperBound if none
}

func search(_ nums: [Int], _ target: Int) -> Int {
    var lo = 0, hi = nums.count - 1
    while lo <= hi {
        let mid = lo + (hi - lo) / 2
        if nums[mid] == target { return mid }
        if nums[mid] < target { lo = mid + 1 } else { hi = mid - 1 }
    }
    return -1
}

func searchRotated(_ nums: [Int], _ target: Int) -> Int {
    var lo = 0, hi = nums.count - 1
    while lo <= hi {
        let mid = lo + (hi - lo) / 2
        if nums[mid] == target { return mid }
        if nums[lo] <= nums[mid] {          // left half is sorted
            if nums[lo] <= target && target < nums[mid] { hi = mid - 1 } else { lo = mid + 1 }
        } else {                            // right half is sorted
            if nums[mid] < target && target <= nums[hi] { lo = mid + 1 } else { hi = mid - 1 }
        }
    }
    return -1
}

func searchMatrix(_ matrix: [[Int]], _ target: Int) -> Bool {
    let rows = matrix.count, cols = matrix.first?.count ?? 0
    var lo = 0, hi = rows * cols - 1
    while lo <= hi {
        let mid = lo + (hi - lo) / 2
        let value = matrix[mid / cols][mid % cols]
        if value == target { return true }
        if value < target { lo = mid + 1 } else { hi = mid - 1 }
    }
    return false
}

func findMin(_ nums: [Int]) -> Int {
    var lo = 0, hi = nums.count - 1
    while lo < hi {
        let mid = lo + (hi - lo) / 2
        if nums[mid] > nums[hi] {
            lo = mid + 1            // the minimum is right of mid
        } else {
            hi = mid                // mid could be the minimum
        }
    }
    return nums[lo]
}

func minEatingSpeed(_ piles: [Int], _ h: Int) -> Int {
    var lo = 1, hi = piles.max() ?? 1
    while lo < hi {
        let speed = lo + (hi - lo) / 2
        let hours = piles.reduce(0) { $0 + ($1 + speed - 1) / speed }
        if hours <= h {
            hi = speed              // fast enough: try slower
        } else {
            lo = speed + 1          // too slow
        }
    }
    return lo
}

func findMedianSortedArrays(_ nums1: [Int], _ nums2: [Int]) -> Double {
    let (a, b) = nums1.count <= nums2.count ? (nums1, nums2) : (nums2, nums1)
    let half = (a.count + b.count + 1) / 2
    var lo = 0, hi = a.count
    while true {
        let i = (lo + hi) / 2           // how many elements the left part takes from a
        let j = half - i                // and from b
        let aLeft = i > 0 ? a[i - 1] : Int.min, aRight = i < a.count ? a[i] : Int.max
        let bLeft = j > 0 ? b[j - 1] : Int.min, bRight = j < b.count ? b[j] : Int.max
        if aLeft > bRight {
            hi = i - 1                  // took too many from a
        } else if bLeft > aRight {
            lo = i + 1                  // took too few from a
        } else {
            let leftMax = max(aLeft, bLeft)
            if (a.count + b.count) % 2 == 1 { return Double(leftMax) }
            return Double(leftMax + min(aRight, bRight)) / 2
        }
    }
}

func nextGreater(_ nums: [Int]) -> [Int] {
    var ans = [Int](repeating: -1, count: nums.count)
    var stack: [Int] = []                  // indices, values decreasing
    for (i, x) in nums.enumerated() {
        while let top = stack.last, nums[top] < x {
            ans[stack.removeLast()] = x
        }
        stack.append(i)
    }
    return ans
}

func dailyTemperatures(_ temps: [Int]) -> [Int] {
    var answer = [Int](repeating: 0, count: temps.count)
    var stack: [Int] = []               // indices of days still waiting
    for (i, t) in temps.enumerated() {
        while let top = stack.last, temps[top] < t {
            answer[stack.removeLast()] = i - top
        }
        stack.append(i)
    }
    return answer
}

func largestRectangleArea(_ heights: [Int]) -> Int {
    var stack: [Int] = []               // indices with increasing heights
    var best = 0
    for i in 0...heights.count {
        let h = i == heights.count ? 0 : heights[i]   // 0 flushes the stack at the end
        while let top = stack.last, heights[top] > h {
            stack.removeLast()
            let left = stack.last ?? -1
            best = max(best, heights[top] * (i - left - 1))
        }
        stack.append(i)
    }
    return best
}

func windowMax(_ nums: [Int], _ k: Int) -> [Int] {
    var dq: [Int] = [], head = 0, out: [Int] = []      // indices, values decreasing
    for i in nums.indices {
        while dq.count > head, nums[dq.last!] <= nums[i] { dq.removeLast() }
        dq.append(i)
        if dq[head] <= i - k { head += 1 }             // front left the window
        if i >= k - 1 { out.append(nums[dq[head]]) }
    }
    return out
}

func maxSlidingWindow(_ nums: [Int], _ k: Int) -> [Int] {
    var deque: [Int] = [], head = 0     // indices; values decrease from head
    var out: [Int] = []
    for i in nums.indices {
        while deque.count > head, nums[deque.last!] <= nums[i] {
            deque.removeLast()
        }
        deque.append(i)
        if deque[head] <= i - k { head += 1 }
        if i >= k - 1 { out.append(nums[deque[head]]) }
    }
    return out
}

func shortestPath(_ adj: [[Int]], from s: Int, to t: Int) -> Int {
    var dist = [Int](repeating: -1, count: adj.count)
    var queue = [s], head = 0
    dist[s] = 0
    while head < queue.count {
        let u = queue[head]; head += 1
        if u == t { return dist[u] }
        for v in adj[u] where dist[v] == -1 {
            dist[v] = dist[u] + 1
            queue.append(v)
        }
    }
    return -1
}

func levelOrder(_ root: TreeNode?) -> [[Int]] {
    guard let root = root else { return [] }
    var result: [[Int]] = []
    var queue = [root]
    while !queue.isEmpty {
        var level: [Int] = []
        var nextQueue: [TreeNode] = []
        for node in queue {
            level.append(node.val)
            if let l = node.left { nextQueue.append(l) }
            if let r = node.right { nextQueue.append(r) }
        }
        result.append(level)
        queue = nextQueue
    }
    return result
}

func orangesRotting(_ grid: [[Int]]) -> Int {
    var g = grid
    let rows = g.count, cols = g.first?.count ?? 0
    var queue: [(Int, Int)] = []
    var fresh = 0
    for r in 0..<rows {
        for c in 0..<cols {
            if g[r][c] == 2 { queue.append((r, c)) }
            if g[r][c] == 1 { fresh += 1 }
        }
    }
    var minutes = 0
    while fresh > 0, !queue.isEmpty {
        var next: [(Int, Int)] = []
        for (r, c) in queue {
            for (dr, dc) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
                let nr = r + dr, nc = c + dc
                guard nr >= 0, nr < rows, nc >= 0, nc < cols, g[nr][nc] == 1 else { continue }
                g[nr][nc] = 2
                fresh -= 1
                next.append((nr, nc))
            }
        }
        queue = next
        minutes += 1
    }
    return fresh == 0 ? minutes : -1
}

func ladderLength(_ beginWord: String, _ endWord: String, _ wordList: [String]) -> Int {
    var remaining = Set(wordList)
    guard remaining.contains(endWord) else { return 0 }
    var queue = [beginWord]
    var steps = 1
    let letters = Array("abcdefghijklmnopqrstuvwxyz")
    while !queue.isEmpty {
        var next: [String] = []
        for word in queue {
            if word == endWord { return steps }
            var chars = Array(word)
            for i in chars.indices {
                let original = chars[i]
                for letter in letters where letter != original {
                    chars[i] = letter
                    let candidate = String(chars)
                    if remaining.remove(candidate) != nil { next.append(candidate) }
                }
                chars[i] = original
            }
        }
        queue = next
        steps += 1
    }
    return 0
}

final class Codec {
    func serialize(_ root: TreeNode?) -> String {
        var parts: [String] = []
        func write(_ node: TreeNode?) {
            guard let node = node else { parts.append("#"); return }
            parts.append(String(node.val))
            write(node.left)
            write(node.right)
        }
        write(root)
        return parts.joined(separator: ",")
    }
    func deserialize(_ data: String) -> TreeNode? {
        let parts = data.split(separator: ",")
        var i = 0
        func read() -> TreeNode? {
            let token = parts[i]; i += 1
            if token == "#" { return nil }
            let node = TreeNode(Int(token)!)
            node.left = read()
            node.right = read()
            return node
        }
        return read()
    }
}

func reachable(_ adj: [[Int]], from s: Int) -> Set<Int> {
    var seen = Set<Int>()
    func visit(_ u: Int) {
        guard seen.insert(u).inserted else { return }
        for v in adj[u] { visit(v) }
    }
    visit(s)
    return seen
}

func isSameTree(_ p: TreeNode?, _ q: TreeNode?) -> Bool {
    guard let p = p, let q = q else { return p == nil && q == nil }
    if p.val != q.val { return false }
    return isSameTree(p.left, q.left)
        && isSameTree(p.right, q.right)
}

func maxDepth(_ root: TreeNode?) -> Int {
    guard let node = root else { return 0 }
    let l = maxDepth(node.left)
    let r = maxDepth(node.right)
    return 1 + max(l, r)
}

func isBalanced(_ root: TreeNode?) -> Bool {
    func height(_ node: TreeNode?) -> Int? {     // nil means unbalanced
        guard let node = node else { return 0 }
        guard let l = height(node.left), let r = height(node.right) else { return nil }
        if abs(l - r) > 1 { return nil }
        return 1 + max(l, r)
    }
    return height(root) != nil
}

func invertTree(_ root: TreeNode?) -> TreeNode? {
    guard let node = root else { return nil }
    let left = invertTree(node.left)
    let right = invertTree(node.right)
    node.left = right
    node.right = left
    return node
}

func diameterOfBinaryTree(_ root: TreeNode?) -> Int {
    var best = 0
    func height(_ node: TreeNode?) -> Int {
        guard let node = node else { return 0 }
        let l = height(node.left)
        let r = height(node.right)
        best = max(best, l + r)     // longest path through this node
        return 1 + max(l, r)
    }
    _ = height(root)
    return best
}

func isSubtree(_ root: TreeNode?, _ subRoot: TreeNode?) -> Bool {
    func same(_ a: TreeNode?, _ b: TreeNode?) -> Bool {
        guard let a = a, let b = b else { return a == nil && b == nil }
        return a.val == b.val && same(a.left, b.left) && same(a.right, b.right)
    }
    guard let root = root else { return subRoot == nil }
    if same(root, subRoot) { return true }
    return isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot)
}

func isValidBST(_ root: TreeNode?) -> Bool {
    func check(_ node: TreeNode?, _ low: Int?, _ high: Int?) -> Bool {
        guard let node = node else { return true }
        if let low = low, node.val <= low { return false }
        if let high = high, node.val >= high { return false }
        return check(node.left, low, node.val)
            && check(node.right, node.val, high)
    }
    return check(root, nil, nil)
}

func kthSmallest(_ root: TreeNode?, _ k: Int) -> Int {
    var stack: [TreeNode] = []
    var node = root
    var remaining = k
    while true {
        while let n = node {
            stack.append(n)             // go as far left as possible
            node = n.left
        }
        let top = stack.removeLast()    // next value in sorted order
        remaining -= 1
        if remaining == 0 { return top.val }
        node = top.right
    }
}

func lowestCommonAncestor(_ root: TreeNode?, _ p: Int, _ q: Int) -> TreeNode? {
    var node = root
    while let n = node {
        if p < n.val && q < n.val {
            node = n.left               // both targets are smaller
        } else if p > n.val && q > n.val {
            node = n.right              // both targets are larger
        } else {
            return n                    // they split here, or one is this node
        }
    }
    return nil
}

func deleteNode(_ root: TreeNode?, _ key: Int) -> TreeNode? {
    guard let root = root else { return nil }
    if key < root.val {
        root.left = deleteNode(root.left, key)
    } else if key > root.val {
        root.right = deleteNode(root.right, key)
    } else {
        guard let left = root.left else { return root.right }
        guard let right = root.right else { return left }
        var successor = right
        while let next = successor.left { successor = next }
        root.val = successor.val
        root.right = deleteNode(right, successor.val)
    }
    return root
}

func insertIntoBST(_ root: TreeNode?, _ val: Int) -> TreeNode? {
    guard let root = root else { return TreeNode(val) }
    var node = root
    while true {
        if val < node.val {
            guard let left = node.left else { node.left = TreeNode(val); break }
            node = left
        } else {
            guard let right = node.right else { node.right = TreeNode(val); break }
            node = right
        }
    }
    return root
}

func maxPathSum(_ root: TreeNode?) -> Int {
    var best = Int.min
    func gain(_ node: TreeNode?) -> Int {
        guard let node = node else { return 0 }
        let l = max(gain(node.left), 0)     // ignore a side that would lose value
        let r = max(gain(node.right), 0)
        best = max(best, node.val + l + r)  // path that bends at this node
        return node.val + max(l, r)         // best single branch for the parent
    }
    _ = gain(root)
    return best
}

func subsets(_ nums: [Int]) -> [[Int]] {
    var out: [[Int]] = [], path: [Int] = []
    func go(_ start: Int) {
        out.append(path)
        for i in start..<nums.count {
            path.append(nums[i])           // choose
            go(i + 1)                      // explore
            path.removeLast()              // un-choose
        }
    }
    go(0)
    return out
}

func combinationSum(_ candidates: [Int], _ target: Int) -> [[Int]] {
    var result: [[Int]] = []
    var path: [Int] = []
    func explore(_ start: Int, _ remaining: Int) {
        if remaining == 0 { result.append(path); return }
        for i in start..<candidates.count where candidates[i] <= remaining {
            path.append(candidates[i])
            explore(i, remaining - candidates[i])   // i, not i + 1: reuse allowed
            path.removeLast()
        }
    }
    explore(0, target)
    return result
}

func permute(_ nums: [Int]) -> [[Int]] {
    var result: [[Int]] = []
    var path: [Int] = []
    var used = [Bool](repeating: false, count: nums.count)
    func build() {
        if path.count == nums.count { result.append(path); return }
        for i in nums.indices where !used[i] {
            used[i] = true
            path.append(nums[i])
            build()
            path.removeLast()
            used[i] = false
        }
    }
    build()
    return result
}

func subsets(_ nums: [Int]) -> [[Int]] {
    var result: [[Int]] = []
    var path: [Int] = []
    func explore(_ start: Int) {
        result.append(path)
        for i in start..<nums.count {
            path.append(nums[i])
            explore(i + 1)
            path.removeLast()
        }
    }
    explore(0)
    return result
}

func exist(_ board: [[Character]], _ word: String) -> Bool {
    var b = board
    let w = Array(word)
    let rows = b.count, cols = b.first?.count ?? 0
    func search(_ r: Int, _ c: Int, _ i: Int) -> Bool {
        if i == w.count { return true }
        guard r >= 0, r < rows, c >= 0, c < cols, b[r][c] == w[i] else { return false }
        b[r][c] = "#"                   // mark as used on this path
        let found = search(r + 1, c, i + 1) || search(r - 1, c, i + 1)
            || search(r, c + 1, i + 1) || search(r, c - 1, i + 1)
        b[r][c] = w[i]                  // restore for other paths
        return found
    }
    for r in 0..<rows {
        for c in 0..<cols where search(r, c, 0) { return true }
    }
    return false
}

func solveNQueens(_ n: Int) -> [[String]] {
    var result: [[String]] = []
    var queens: [Int] = []              // queens[row] = column
    var cols = Set<Int>(), diag = Set<Int>(), anti = Set<Int>()
    func place(_ row: Int) {
        if row == n {
            result.append(queens.map { c in (0..<n).map { $0 == c ? "Q" : "." }.joined() })
            return
        }
        for c in 0..<n where !cols.contains(c) && !diag.contains(row - c) && !anti.contains(row + c) {
            queens.append(c); cols.insert(c); diag.insert(row - c); anti.insert(row + c)
            place(row + 1)
            queens.removeLast(); cols.remove(c); diag.remove(row - c); anti.remove(row + c)
        }
    }
    place(0)
    return result
}

func canReachEnd(_ jumps: [Int]) -> Bool {
    var farthest = 0
    for (i, j) in jumps.enumerated() {
        if i > farthest { return false }   // stuck before i
        farthest = max(farthest, i + j)
    }
    return true
}

func maxProfit(_ prices: [Int]) -> Int {
    var minPrice = Int.max
    var best = 0
    for p in prices {
        minPrice = min(minPrice, p)
        best = max(best, p - minPrice)
    }
    return best
}

func jump(_ nums: [Int]) -> Int {
    var jumps = 0, end = 0, farthest = 0
    for i in 0..<max(nums.count - 1, 0) {
        farthest = max(farthest, i + nums[i])
        if i == end {               // used up the current jump's range
            jumps += 1
            end = farthest
        }
    }
    return jumps
}

func canJump(_ nums: [Int]) -> Bool {
    var farthest = 0
    for (i, jump) in nums.enumerated() {
        if i > farthest { return false }
        farthest = max(farthest, i + jump)
    }
    return true
}

func canCompleteCircuit(_ gas: [Int], _ cost: [Int]) -> Int {
    var total = 0, tank = 0, start = 0
    for i in gas.indices {
        let gain = gas[i] - cost[i]
        total += gain
        tank += gain
        if tank < 0 {               // cannot reach i + 1 from the current start
            start = i + 1
            tank = 0
        }
    }
    return total >= 0 ? start : -1
}

func minCostConnectPoints(_ points: [[Int]]) -> Int {
    let n = points.count
    var inTree = [Bool](repeating: false, count: n)
    var best = [Int](repeating: Int.max, count: n)   // cheapest edge into the tree
    var total = 0
    if n > 0 { best[0] = 0 }
    for _ in 0..<n {
        var u = -1
        for v in 0..<n where !inTree[v] {
            if u == -1 || best[v] < best[u] { u = v }
        }
        inTree[u] = true
        total += best[u]
        for v in 0..<n where !inTree[v] {
            let d = abs(points[u][0] - points[v][0]) + abs(points[u][1] - points[v][1])
            best[v] = min(best[v], d)
        }
    }
    return total
}

func minCostConnectPointsKruskal(_ points: [[Int]]) -> Int {
    let n = points.count
    var edges: [(cost: Int, a: Int, b: Int)] = []
    for a in 0..<n {
        for b in (a + 1)..<n {
            let cost = abs(points[a][0] - points[b][0]) + abs(points[a][1] - points[b][1])
            edges.append((cost, a, b))
        }
    }
    edges.sort { $0.cost < $1.cost }
    var parent = Array(0..<n)
    func find(_ x: Int) -> Int {
        var x = x
        while parent[x] != x { parent[x] = parent[parent[x]]; x = parent[x] }
        return x
    }
    var total = 0, used = 0
    for e in edges where used < n - 1 {
        let ra = find(e.a), rb = find(e.b)
        if ra != rb {
            parent[ra] = rb
            total += e.cost
            used += 1
        }
    }
    return total
}

func maxLoot(_ houses: [Int]) -> Int {
    var skip = 0, take = 0                 // best without / with previous house
    for h in houses {
        (skip, take) = (max(skip, take), skip + h)
    }
    return max(skip, take)
}

func climbStairs(_ n: Int) -> Int {
    var a = 1, b = 1                    // ways(0), ways(1)
    for _ in 0..<n {
        (a, b) = (b, a + b)
    }
    return a
}

func longestPalindrome(_ s: String) -> String {
    let chars = Array(s)
    var start = 0, length = 0
    for center in 0..<max(2 * chars.count - 1, 0) {
        var l = center / 2, r = l + center % 2
        while l >= 0, r < chars.count, chars[l] == chars[r] {
            l -= 1; r += 1
        }
        if r - l - 1 > length {
            length = r - l - 1
            start = l + 1
        }
    }
    return String(chars[start..<start + length])
}

func maxSubArray(_ nums: [Int]) -> Int {
    var cur = nums[0], best = nums[0]
    for x in nums.dropFirst() {
        cur = max(x, cur + x)
        best = max(best, cur)
    }
    return best
}

func uniquePaths(_ m: Int, _ n: Int) -> Int {
    var row = [Int](repeating: 1, count: n)   // one way along the top edge
    for _ in 1..<m {
        for c in 1..<n {
            row[c] += row[c - 1]              // from above + from the left
        }
    }
    return row[n - 1]
}

func numDecodings(_ s: String) -> Int {
    let d = s.compactMap { $0.wholeNumberValue }
    guard !d.isEmpty, d[0] != 0 else { return 0 }
    var prev = 1, cur = 1               // ways for the prefixes one shorter and current
    for i in 1..<d.count {
        var next = 0
        if d[i] != 0 { next += cur }                    // decode one digit
        let two = d[i - 1] * 10 + d[i]
        if two >= 10 && two <= 26 { next += prev }      // decode two digits
        (prev, cur) = (cur, next)
    }
    return cur
}

func wordBreak(_ s: String, _ wordDict: [String]) -> Bool {
    let chars = Array(s)
    let words = Set(wordDict)
    var dp = [Bool](repeating: false, count: chars.count + 1)
    dp[0] = true                    // the empty prefix can be built
    for end in stride(from: 1, through: chars.count, by: 1) {
        for start in 0..<end where dp[start] {
            if words.contains(String(chars[start..<end])) {
                dp[end] = true
                break
            }
        }
    }
    return dp[chars.count]
}

func maxProduct(_ nums: [Int]) -> Int {
    var hi = nums[0], lo = nums[0], best = nums[0]
    for x in nums.dropFirst() {
        let candidates = [x, hi * x, lo * x]
        hi = candidates.max()!
        lo = candidates.min()!
        best = max(best, hi)
    }
    return best
}

func rob(_ nums: [Int]) -> Int {
    var prev = 0, cur = 0               // best up to i-2, best up to i-1
    for x in nums {
        (prev, cur) = (cur, max(cur, prev + x))
    }
    return cur
}

func robCircle(_ nums: [Int]) -> Int {
    if nums.count == 1 { return nums[0] }
    func robLine(_ houses: ArraySlice<Int>) -> Int {
        var prev = 0, cur = 0
        for x in houses {
            (prev, cur) = (cur, max(cur, prev + x))
        }
        return cur
    }
    return max(robLine(nums.dropLast()), robLine(nums.dropFirst()))
}

func lengthOfLIS(_ nums: [Int]) -> Int {
    var dp = [Int](repeating: 1, count: nums.count)   // longest ending at i
    for i in nums.indices {
        for j in 0..<i where nums[j] < nums[i] {
            dp[i] = max(dp[i], dp[j] + 1)
        }
    }
    return dp.max() ?? 0
}

func coinChange(_ coins: [Int], _ amount: Int) -> Int {
    var dp = [Int](repeating: amount + 1, count: amount + 1)
    dp[0] = 0
    for a in stride(from: 1, through: amount, by: 1) {
        for coin in coins where coin <= a {
            dp[a] = min(dp[a], dp[a - coin] + 1)
        }
    }
    return dp[amount] > amount ? -1 : dp[amount]
}

func canPartition(_ nums: [Int]) -> Bool {
    let total = nums.reduce(0, +)
    if total % 2 != 0 { return false }
    let target = total / 2
    var reach = [Bool](repeating: false, count: target + 1)
    reach[0] = true
    for x in nums {
        for s in stride(from: target, through: x, by: -1) where reach[s - x] {
            reach[s] = true
        }
    }
    return reach[target]
}

func longestCommonSubsequence(_ text1: String, _ text2: String) -> Int {
    let a = Array(text1), b = Array(text2)
    var dp = [[Int]](repeating: [Int](repeating: 0, count: b.count + 1), count: a.count + 1)
    for i in stride(from: 1, through: a.count, by: 1) {
        for j in stride(from: 1, through: b.count, by: 1) {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
            }
        }
    }
    return dp[a.count][b.count]
}

struct MinHeap<T: Comparable> {
    private var a: [T] = []
    var count: Int { a.count }
    var peek: T? { a.first }
    mutating func push(_ x: T) {
        a.append(x)
        var i = a.count - 1
        while i > 0, a[(i - 1) / 2] > a[i] {
            a.swapAt((i - 1) / 2, i); i = (i - 1) / 2
        }
    }
    mutating func pop() -> T? {
        guard !a.isEmpty else { return nil }
        a.swapAt(0, a.count - 1)
        let top = a.removeLast()
        var i = 0
        while true {
            let l = 2 * i + 1, r = l + 1
            var m = i
            if l < a.count, a[l] < a[m] { m = l }
            if r < a.count, a[r] < a[m] { m = r }
            if m == i { break }
            a.swapAt(i, m); i = m
        }
        return top
    }
}
func kLargest(_ nums: [Int], _ k: Int) -> [Int] {
    var heap = MinHeap<Int>()
    for x in nums {
        heap.push(x)
        if heap.count > k { _ = heap.pop() }   // drop the smallest
    }
    var out: [Int] = []
    while let x = heap.pop() { out.append(x) }
    return out
}

struct KthLargest {
    private var heap: [Int] = []        // min-heap of the k largest values
    private let k: Int
    init(_ k: Int, _ nums: [Int]) {
        self.k = k
        for x in nums { _ = add(x) }
    }
    mutating func add(_ val: Int) -> Int {
        heap.append(val)
        var i = heap.count - 1
        while i > 0, heap[(i - 1) / 2] > heap[i] {      // sift up
            heap.swapAt((i - 1) / 2, i); i = (i - 1) / 2
        }
        if heap.count > k { removeMin() }
        return heap[0]
    }
    private mutating func removeMin() {
        heap.swapAt(0, heap.count - 1)
        heap.removeLast()
        var i = 0
        while true {                                     // sift down
            var m = i
            for c in [2 * i + 1, 2 * i + 2] where c < heap.count && heap[c] < heap[m] { m = c }
            if m == i { return }
            heap.swapAt(i, m); i = m
        }
    }
}

func findKthLargest(_ nums: [Int], _ k: Int) -> Int {
    var heap: [Int] = []                 // min-heap holding the k largest so far
    func siftUp(_ start: Int) {
        var i = start
        while i > 0, heap[(i - 1) / 2] > heap[i] {
            heap.swapAt((i - 1) / 2, i)
            i = (i - 1) / 2
        }
    }
    func siftDown() {
        var i = 0
        while true {
            var m = i
            for c in [2 * i + 1, 2 * i + 2] where c < heap.count && heap[c] < heap[m] { m = c }
            if m == i { return }
            heap.swapAt(i, m)
            i = m
        }
    }
    for x in nums {
        if heap.count < k {
            heap.append(x)
            siftUp(heap.count - 1)
        } else if x > heap[0] {
            heap[0] = x
            siftDown()
        }
    }
    return heap[0]
}

func findKthLargestQuick(_ nums: [Int], _ k: Int) -> Int {
    var a = nums
    let target = a.count - k            // its index in ascending order
    var lo = 0, hi = a.count - 1
    while true {
        let pivot = a[hi]
        var store = lo
        for i in lo..<hi where a[i] < pivot {
            a.swapAt(i, store)
            store += 1
        }
        a.swapAt(store, hi)             // the pivot is now in its final place
        if store == target { return a[store] }
        if store < target { lo = store + 1 } else { hi = store - 1 }
    }
}

func topKFrequent(_ nums: [Int], _ k: Int) -> [Int] {
    var freq: [Int: Int] = [:]
    for x in nums { freq[x, default: 0] += 1 }
    var buckets = [[Int]](repeating: [], count: nums.count + 1)
    for (x, f) in freq { buckets[f].append(x) }
    var out: [Int] = []
    for f in stride(from: nums.count, to: 0, by: -1) {
        for x in buckets[f] where out.count < k { out.append(x) }
    }
    return out
}

func mergeKLists(_ lists: [ListNode?]) -> ListNode? {
    var heap: [ListNode] = []           // min-heap ordered by node value
    func siftUp(_ start: Int) {
        var i = start
        while i > 0, heap[(i - 1) / 2].val > heap[i].val {
            heap.swapAt((i - 1) / 2, i); i = (i - 1) / 2
        }
    }
    func siftDown() {
        var i = 0
        while true {
            var m = i
            for c in [2 * i + 1, 2 * i + 2] where c < heap.count && heap[c].val < heap[m].val { m = c }
            if m == i { return }
            heap.swapAt(i, m); i = m
        }
    }
    for case let node? in lists { heap.append(node); siftUp(heap.count - 1) }
    let dummy = ListNode(0)
    var tail = dummy
    while let smallest = heap.first {
        tail.next = smallest
        tail = smallest
        if let next = smallest.next {
            heap[0] = next               // replace the root with its successor
        } else {
            heap[0] = heap[heap.count - 1]
            heap.removeLast()
        }
        if !heap.isEmpty { siftDown() }
    }
    return dummy.next
}

struct Heap {
    private var items: [Int] = []
    private let before: (Int, Int) -> Bool      // true if a belongs nearer the top than b
    init(_ before: @escaping (Int, Int) -> Bool) { self.before = before }
    var count: Int { items.count }
    var top: Int? { items.first }
    mutating func push(_ x: Int) {
        items.append(x)
        var i = items.count - 1
        while i > 0, before(items[i], items[(i - 1) / 2]) {
            items.swapAt(i, (i - 1) / 2); i = (i - 1) / 2
        }
    }
    mutating func pop() -> Int? {
        guard !items.isEmpty else { return nil }
        items.swapAt(0, items.count - 1)
        let top = items.removeLast()
        var i = 0
        while true {
            var m = i
            for c in [2 * i + 1, 2 * i + 2] where c < items.count && before(items[c], items[m]) { m = c }
            if m == i { break }
            items.swapAt(i, m); i = m
        }
        return top
    }
}
struct MedianFinder {
    private var low = Heap(>)           // max-heap: the smaller half
    private var high = Heap(<)          // min-heap: the larger half
    mutating func addNum(_ num: Int) {
        low.push(num)
        high.push(low.pop()!)           // pass the largest of low across
        if high.count > low.count { low.push(high.pop()!) }
    }
    func findMedian() -> Double {
        low.count > high.count ? Double(low.top!) : Double(low.top! + high.top!) / 2
    }
}

func topoOrder(_ n: Int, _ edges: [(from: Int, to: Int)]) -> [Int]? {
    var adj = [[Int]](repeating: [], count: n)
    var indeg = [Int](repeating: 0, count: n)
    for e in edges { adj[e.from].append(e.to); indeg[e.to] += 1 }
    var ready = (0..<n).filter { indeg[$0] == 0 }, order: [Int] = []
    while let u = ready.popLast() {
        order.append(u)
        for v in adj[u] {
            indeg[v] -= 1
            if indeg[v] == 0 { ready.append(v) }
        }
    }
    return order.count == n ? order : nil  // nil means a cycle exists
}

func cloneGraph(_ node: GraphNode?) -> GraphNode? {
    var copies: [Int: GraphNode] = [:]      // original value -> its copy
    func clone(_ original: GraphNode) -> GraphNode {
        if let done = copies[original.val] { return done }
        let copy = GraphNode(original.val)
        copies[original.val] = copy             // register before visiting neighbours
        for neighbour in original.neighbors {
            copy.neighbors.append(clone(neighbour))
        }
        return copy
    }
    return node.map(clone)
}

func numIslands(_ grid: [[Character]]) -> Int {
    var g = grid
    let rows = g.count, cols = g.first?.count ?? 0
    func sink(_ r: Int, _ c: Int) {
        guard r >= 0, r < rows, c >= 0, c < cols, g[r][c] == "1" else { return }
        g[r][c] = "0"
        sink(r + 1, c); sink(r - 1, c); sink(r, c + 1); sink(r, c - 1)
    }
    var count = 0
    for r in 0..<rows {
        for c in 0..<cols where g[r][c] == "1" {
            count += 1
            sink(r, c)
        }
    }
    return count
}

func canFinish(_ numCourses: Int, _ prerequisites: [[Int]]) -> Bool {
    var adj = [[Int]](repeating: [], count: numCourses)
    var indegree = [Int](repeating: 0, count: numCourses)
    for p in prerequisites {
        adj[p[1]].append(p[0])          // p[1] must come before p[0]
        indegree[p[0]] += 1
    }
    var ready = (0..<numCourses).filter { indegree[$0] == 0 }
    var taken = 0
    while let course = ready.popLast() {
        taken += 1
        for next in adj[course] {
            indegree[next] -= 1
            if indegree[next] == 0 { ready.append(next) }
        }
    }
    return taken == numCourses
}

func findOrder(_ numCourses: Int, _ prerequisites: [[Int]]) -> [Int] {
    var adj = [[Int]](repeating: [], count: numCourses)
    var indegree = [Int](repeating: 0, count: numCourses)
    for p in prerequisites {
        adj[p[1]].append(p[0])
        indegree[p[0]] += 1
    }
    var queue = (0..<numCourses).filter { indegree[$0] == 0 }
    var head = 0
    while head < queue.count {
        let course = queue[head]; head += 1
        for next in adj[course] {
            indegree[next] -= 1
            if indegree[next] == 0 { queue.append(next) }
        }
    }
    return queue.count == numCourses ? queue : []
}

func pacificAtlantic(_ heights: [[Int]]) -> [[Int]] {
    let rows = heights.count, cols = heights.first?.count ?? 0
    var pacific = [[Bool]](repeating: [Bool](repeating: false, count: cols), count: rows)
    var atlantic = pacific
    func climb(_ r: Int, _ c: Int, _ seen: inout [[Bool]], _ from: Int) {
        guard r >= 0, r < rows, c >= 0, c < cols, !seen[r][c], heights[r][c] >= from else { return }
        seen[r][c] = true
        for (dr, dc) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            climb(r + dr, c + dc, &seen, heights[r][c])
        }
    }
    for r in 0..<rows {
        climb(r, 0, &pacific, 0)
        climb(r, cols - 1, &atlantic, 0)
    }
    for c in 0..<cols {
        climb(0, c, &pacific, 0)
        climb(rows - 1, c, &atlantic, 0)
    }
    var result: [[Int]] = []
    for r in 0..<rows {
        for c in 0..<cols where pacific[r][c] && atlantic[r][c] { result.append([r, c]) }
    }
    return result
}

func maxAreaOfIsland(_ grid: [[Int]]) -> Int {
    var g = grid
    let rows = g.count, cols = g.first?.count ?? 0
    func area(_ r: Int, _ c: Int) -> Int {
        guard r >= 0, r < rows, c >= 0, c < cols, g[r][c] == 1 else { return 0 }
        g[r][c] = 0
        return 1 + area(r + 1, c) + area(r - 1, c) + area(r, c + 1) + area(r, c - 1)
    }
    var best = 0
    for r in 0..<rows {
        for c in 0..<cols where g[r][c] == 1 {
            best = max(best, area(r, c))
        }
    }
    return best
}

func networkDelayTime(_ times: [[Int]], _ n: Int, _ k: Int) -> Int {
    var adj = [[(to: Int, w: Int)]](repeating: [], count: n + 1)
    for t in times { adj[t[0]].append((t[1], t[2])) }
    var dist = [Int](repeating: Int.max, count: n + 1)
    var done = [Bool](repeating: false, count: n + 1)
    dist[k] = 0
    for _ in 0..<n {
        var u = -1
        for v in 1...n where !done[v] && dist[v] != Int.max {
            if u == -1 || dist[v] < dist[u] { u = v }
        }
        if u == -1 { break }
        done[u] = true
        for e in adj[u] where dist[u] + e.w < dist[e.to] {
            dist[e.to] = dist[u] + e.w
        }
    }
    let worst = dist[1...].max()!
    return worst == Int.max ? -1 : worst
}

func findCheapestPrice(_ n: Int, _ flights: [[Int]], _ src: Int, _ dst: Int, _ k: Int) -> Int {
    var cost = [Int](repeating: Int.max, count: n)
    cost[src] = 0
    for _ in 0...k {                     // at most k stops = k + 1 flights
        var next = cost                  // a round reads only the previous round
        for f in flights where cost[f[0]] != Int.max {
            next[f[1]] = min(next[f[1]], cost[f[0]] + f[2])
        }
        cost = next
    }
    return cost[dst] == Int.max ? -1 : cost[dst]
}

struct UnionFind {
    private var parent: [Int], size: [Int]
    init(_ n: Int) { parent = Array(0..<n); size = Array(repeating: 1, count: n) }
    mutating func find(_ x: Int) -> Int {
        if parent[x] != x { parent[x] = find(parent[x]) }   // path compression
        return parent[x]
    }
    @discardableResult
    mutating func union(_ a: Int, _ b: Int) -> Bool {
        var (ra, rb) = (find(a), find(b))
        if ra == rb { return false }
        if size[ra] < size[rb] { swap(&ra, &rb) }
        parent[rb] = ra; size[ra] += size[rb]               // small under large
        return true
    }
}

func countComponents(_ n: Int, _ edges: [[Int]]) -> Int {
    var parent = Array(0..<n)
    func find(_ x: Int) -> Int {
        var x = x
        while parent[x] != x { parent[x] = parent[parent[x]]; x = parent[x] }
        return x
    }
    var count = n
    for e in edges {
        let a = find(e[0]), b = find(e[1])
        if a != b { parent[a] = b; count -= 1 }
    }
    return count
}

func findCircleNum(_ isConnected: [[Int]]) -> Int {
    let n = isConnected.count
    var parent = Array(0..<n)
    func find(_ x: Int) -> Int {
        var x = x
        while parent[x] != x {
            parent[x] = parent[parent[x]]   // path halving
            x = parent[x]
        }
        return x
    }
    var count = n
    for i in 0..<n {
        for j in (i + 1)..<n where isConnected[i][j] == 1 {
            let a = find(i), b = find(j)
            if a != b { parent[a] = b; count -= 1 }
        }
    }
    return count
}

func findRedundantConnection(_ edges: [[Int]]) -> [Int] {
    var parent = Array(0...edges.count)
    func find(_ x: Int) -> Int {
        var x = x
        while parent[x] != x {
            parent[x] = parent[parent[x]]
            x = parent[x]
        }
        return x
    }
    for edge in edges {
        let a = find(edge[0]), b = find(edge[1])
        if a == b { return edge }       // already connected: this edge closes a cycle
        parent[a] = b
    }
    return []
}

final class Trie {
    private final class Node { var next: [Character: Node] = [:]; var isWord = false }
    private let root = Node()
    func insert(_ word: String) {
        var n = root
        for ch in word {
            if n.next[ch] == nil { n.next[ch] = Node() }
            n = n.next[ch]!
        }
        n.isWord = true
    }
    func words(withPrefix prefix: String, limit: Int = 5) -> [String] {
        var n = root
        for ch in prefix { guard let m = n.next[ch] else { return [] }; n = m }
        var out: [String] = []
        func collect(_ node: Node, _ cur: String) {
            if out.count == limit { return }
            if node.isWord { out.append(cur) }
            for (ch, child) in node.next.sorted(by: { $0.key < $1.key }) {
                collect(child, cur + String(ch))
            }
        }
        collect(n, prefix)
        return out
    }
}

final class Trie {
    private final class Node {
        var children: [Character: Node] = [:]
        var isWord = false
    }
    private let root = Node()
    func insert(_ word: String) {
        var node = root
        for ch in word {
            if node.children[ch] == nil { node.children[ch] = Node() }
            node = node.children[ch]!
        }
        node.isWord = true
    }
    private func walk(_ text: String) -> Node? {
        var node = root
        for ch in text {
            guard let next = node.children[ch] else { return nil }
            node = next
        }
        return node
    }
    func search(_ word: String) -> Bool { walk(word)?.isWord ?? false }
    func startsWith(_ prefix: String) -> Bool { walk(prefix) != nil }
}

final class WordDictionary {
    private final class Node { var next: [Character: Node] = [:]; var isWord = false }
    private let root = Node()
    func addWord(_ word: String) {
        var node = root
        for ch in word {
            if node.next[ch] == nil { node.next[ch] = Node() }
            node = node.next[ch]!
        }
        node.isWord = true
    }
    func search(_ word: String) -> Bool {
        let chars = Array(word)
        func match(_ node: Node, _ i: Int) -> Bool {
            if i == chars.count { return node.isWord }
            if chars[i] == "." {
                return node.next.values.contains { match($0, i + 1) }
            }
            guard let child = node.next[chars[i]] else { return false }
            return match(child, i + 1)
        }
        return match(root, 0)
    }
}

func findWords(_ board: [[Character]], _ words: [String]) -> [String] {
    final class Node { var next: [Character: Node] = [:]; var word: String? }
    let root = Node()
    for w in words {
        var n = root
        for ch in w {
            if n.next[ch] == nil { n.next[ch] = Node() }
            n = n.next[ch]!
        }
        n.word = w
    }
    var b = board
    let rows = b.count, cols = b.first?.count ?? 0
    var found: [String] = []
    func search(_ r: Int, _ c: Int, _ node: Node) {
        guard r >= 0, r < rows, c >= 0, c < cols, let child = node.next[b[r][c]] else { return }
        if let w = child.word { found.append(w); child.word = nil }   // report each word once
        let ch = b[r][c]
        b[r][c] = "#"
        search(r + 1, c, child); search(r - 1, c, child)
        search(r, c + 1, child); search(r, c - 1, child)
        b[r][c] = ch
    }
    for r in 0..<rows { for c in 0..<cols { search(r, c, root) } }
    return found
}

func singleNumber(_ nums: [Int]) -> Int { nums.reduce(0, ^) }   // pairs cancel
func bitCount(_ x: UInt) -> Int {
    var n = x, c = 0
    while n != 0 { n &= n - 1; c += 1 }    // clears the lowest set bit
    return c
}

func singleNumber(_ nums: [Int]) -> Int {
    var acc = 0
    for x in nums {
        acc ^= x
    }
    return acc
}

func reverseBits(_ n: Int) -> Int {
    var x = n, result = 0
    for _ in 0..<32 {
        result = (result << 1) | (x & 1)
        x >>= 1
    }
    return result
}

func hammingWeight(_ n: Int) -> Int {
    var x = n, count = 0
    while x != 0 {
        x &= x - 1                  // clears the lowest set bit
        count += 1
    }
    return count
}

func missingNumber(_ nums: [Int]) -> Int {
    var acc = nums.count
    for (i, x) in nums.enumerated() {
        acc ^= i ^ x
    }
    return acc
}

func countBits(_ n: Int) -> [Int] {
    var bits = [Int](repeating: 0, count: n + 1)
    for i in stride(from: 1, through: n, by: 1) {
        bits[i] = bits[i >> 1] + (i & 1)
    }
    return bits
}

func mergeRanges(_ ranges: [ClosedRange<Int>]) -> [ClosedRange<Int>] {
    var out: [ClosedRange<Int>] = []
    for r in ranges.sorted(by: { $0.lowerBound < $1.lowerBound }) {
        if let last = out.last, r.lowerBound <= last.upperBound {
            out[out.count - 1] = last.lowerBound...max(last.upperBound, r.upperBound)
        } else {
            out.append(r)
        }
    }
    return out
}

func canAttendMeetings(_ intervals: [[Int]]) -> Bool {
    let sorted = intervals.sorted { $0[0] < $1[0] }
    for i in sorted.indices.dropFirst() {
        if sorted[i][0] < sorted[i - 1][1] { return false }
    }
    return true
}

func merge(_ intervals: [[Int]]) -> [[Int]] {
    let sorted = intervals.sorted { $0[0] < $1[0] }
    var out: [[Int]] = []
    for iv in sorted {
        if let last = out.last, iv[0] <= last[1] {
            out[out.count - 1][1] = max(last[1], iv[1])
        } else {
            out.append(iv)
        }
    }
    return out
}

func insert(_ intervals: [[Int]], _ newInterval: [Int]) -> [[Int]] {
    var out: [[Int]] = []
    var cur = newInterval
    var i = 0
    while i < intervals.count, intervals[i][1] < cur[0] {
        out.append(intervals[i]); i += 1          // ends before cur starts
    }
    while i < intervals.count, intervals[i][0] <= cur[1] {
        cur = [min(cur[0], intervals[i][0]), max(cur[1], intervals[i][1])]
        i += 1                                    // overlaps: absorb it
    }
    out.append(cur)
    out.append(contentsOf: intervals[i...])
    return out
}

func minMeetingRooms(_ intervals: [[Int]]) -> Int {
    let starts = intervals.map { $0[0] }.sorted()
    let ends = intervals.map { $0[1] }.sorted()
    var rooms = 0, best = 0, e = 0
    for s in starts {
        while e < ends.count, ends[e] <= s {
            rooms -= 1; e += 1          // a meeting has ended: its room is free
        }
        rooms += 1
        best = max(best, rooms)
    }
    return best
}

func eraseOverlapIntervals(_ intervals: [[Int]]) -> Int {
    let sorted = intervals.sorted { $0[1] < $1[1] }
    var removed = 0
    var lastEnd = Int.min
    for iv in sorted {
        if iv[0] >= lastEnd {
            lastEnd = iv[1]         // keep it
        } else {
            removed += 1            // overlaps the last kept interval
        }
    }
    return removed
}

func mergeSort(_ a: [Int]) -> [Int] {
    guard a.count > 1 else { return a }
    let mid = a.count / 2
    let l = mergeSort(Array(a[..<mid])), r = mergeSort(Array(a[mid...]))
    var out: [Int] = [], i = 0, j = 0
    out.reserveCapacity(a.count)
    while i < l.count, j < r.count {
        if l[i] <= r[j] { out.append(l[i]); i += 1 } else { out.append(r[j]); j += 1 }
    }
    return out + l[i...] + r[j...]
}

func buildTree(_ preorder: [Int], _ inorder: [Int]) -> TreeNode? {
    var position: [Int: Int] = [:]      // value -> index in inorder
    for (i, v) in inorder.enumerated() { position[v] = i }
    var next = 0                        // next root in preorder
    func build(_ lo: Int, _ hi: Int) -> TreeNode? {
        if lo > hi { return nil }
        let node = TreeNode(preorder[next])
        next += 1
        let mid = position[node.val]!
        node.left = build(lo, mid - 1)      // everything left of it in inorder
        node.right = build(mid + 1, hi)
        return node
    }
    return build(0, inorder.count - 1)
}

func sortList(_ head: ListNode?) -> ListNode? {
    guard let head = head, head.next != nil else { return head }
    var slow = head, fast = head.next
    while let next = fast?.next {
        slow = slow.next!
        fast = next.next
    }
    let second = slow.next
    slow.next = nil                     // split into two halves
    var a = sortList(head), b = sortList(second)
    let dummy = ListNode(0)
    var tail = dummy
    while let x = a, let y = b {
        if x.val <= y.val { tail.next = x; a = x.next } else { tail.next = y; b = y.next }
        tail = tail.next!
    }
    tail.next = a ?? b
    return dummy.next
}

func sortArray(_ nums: [Int]) -> [Int] {
    guard nums.count > 1 else { return nums }
    let mid = nums.count / 2
    let left = sortArray(Array(nums[..<mid]))
    let right = sortArray(Array(nums[mid...]))
    var merged: [Int] = []
    merged.reserveCapacity(nums.count)
    var i = 0, j = 0
    while i < left.count, j < right.count {
        if left[i] <= right[j] { merged.append(left[i]); i += 1 }
        else { merged.append(right[j]); j += 1 }
    }
    return merged + left[i...] + right[j...]
}

func isValid(_ s: String) -> Bool {
    let pairs: [Character: Character] = [")": "(", "]": "[", "}": "{"]
    var stack: [Character] = []
    for ch in s {
        if let open = pairs[ch] {
            if stack.popLast() != open { return false }
        } else {
            stack.append(ch)
        }
    }
    return stack.isEmpty
}

struct MyQueue {
    private var inbox: [Int] = [], outbox: [Int] = []
    mutating func push(_ x: Int) { inbox.append(x) }
    private mutating func refill() {
        if outbox.isEmpty {
            while let x = inbox.popLast() { outbox.append(x) }
        }
    }
    mutating func pop() -> Int { refill(); return outbox.removeLast() }
    mutating func peek() -> Int { refill(); return outbox.last! }
    var empty: Bool { inbox.isEmpty && outbox.isEmpty }
}

func evalRPN(_ tokens: [String]) -> Int {
    var stack: [Int] = []
    for token in tokens {
        if let number = Int(token) {
            stack.append(number)
            continue
        }
        let b = stack.removeLast(), a = stack.removeLast()
        switch token {
        case "+": stack.append(a + b)
        case "-": stack.append(a - b)
        case "*": stack.append(a * b)
        default: stack.append(a / b)     // Swift's / truncates toward zero
        }
    }
    return stack[0]
}

