final class LRUCache<Key: Hashable, Value> {
    private final class Node {
        let key: Key; var value: Value; var prev: Node?; var next: Node?
        init(_ k: Key, _ v: Value) { key = k; value = v }
    }
    private var map: [Key: Node] = [:]
    private var head: Node?, tail: Node?                 // head = most recent
    private let capacity: Int
    init(capacity: Int) { self.capacity = max(1, capacity) }
    private func detach(_ n: Node) {
        n.prev?.next = n.next; n.next?.prev = n.prev
        if head === n { head = n.next }
        if tail === n { tail = n.prev }
        n.prev = nil; n.next = nil
    }
    private func pushFront(_ n: Node) {
        n.next = head; head?.prev = n; head = n
        if tail == nil { tail = n }
    }
    func get(_ key: Key) -> Value? {
        guard let n = map[key] else { return nil }
        detach(n); pushFront(n)
        return n.value
    }
    func set(_ key: Key, _ value: Value) {
        if let n = map[key] { n.value = value; detach(n); pushFront(n); return }
        if map.count == capacity, let old = tail { detach(old); map[old.key] = nil }
        let n = Node(key, value)
        map[key] = n; pushFront(n)
    }
}

struct Stop: Comparable {
    let cost: Int, node: Int
    static func < (a: Stop, b: Stop) -> Bool { a.cost < b.cost }
}
func cheapestCosts(_ adj: [[(to: Int, cost: Int)]], from s: Int) -> [Int] {
    var dist = [Int](repeating: Int.max, count: adj.count)
    var heap = MinHeap<Stop>()
    dist[s] = 0; heap.push(Stop(cost: 0, node: s))
    while let cur = heap.pop() {
        if cur.cost > dist[cur.node] { continue }        // stale entry
        for e in adj[cur.node] where cur.cost + e.cost < dist[e.to] {
            dist[e.to] = cur.cost + e.cost
            heap.push(Stop(cost: dist[e.to], node: e.to))
        }
    }
    return dist
}

struct Job: Comparable {
    let priority: Int, name: String                      // lower number = sooner
    static func < (a: Job, b: Job) -> Bool { a.priority < b.priority }
}
func runOrder(_ jobs: [Job]) -> [String] {
    var heap = MinHeap<Job>()
    jobs.forEach { heap.push($0) }
    var out: [String] = []
    while let j = heap.pop() { out.append(j.name) }
    return out
}

struct Scored: Comparable {
    let score: Double, id: String
    static func < (a: Scored, b: Scored) -> Bool { a.score < b.score }
}
func topRecommendations(_ items: [Scored], _ k: Int) -> [String] {
    var heap = MinHeap<Scored>()                         // keeps the k best
    for it in items {
        heap.push(it)
        if heap.count > k { _ = heap.pop() }
    }
    var out: [String] = []
    while let it = heap.pop() { out.append(it.id) }
    return out.reversed()                                // best first
}

func topoOrder(_ n: Int, _ edges: [(from: Int, to: Int)]) -> [Int]? {
    var adj = [[Int]](repeating: [], count: n)
    var indeg = [Int](repeating: 0, count: n)
    for e in edges { adj[e.from].append(e.to); indeg[e.to] += 1 }
    var ready = (0..<n).filter { indeg[$0] == 0 }, order: [Int] = []
    while let u = ready.popLast() {
        order.append(u)
        for v in adj[u] {
            indeg[v] -= 1
            if indeg[v] == 0 { ready.append(v) }
        }
    }
    return order.count == n ? order : nil  // nil means a cycle exists
}

struct SearchIndex {
    private var postings: [String: Set<Int>] = [:]       // word -> document ids
    mutating func add(_ id: Int, _ text: String) {
        for w in text.lowercased().split(whereSeparator: { !$0.isLetter && !$0.isNumber }) {
            postings[String(w), default: []].insert(id)
        }
    }
    func search(_ query: String) -> Set<Int> {
        let sets = query.lowercased().split(separator: " ").map { postings[String($0)] ?? [] }
        guard var hit = sets.first else { return [] }
        for s in sets.dropFirst() { hit.formIntersection(s) }
        return hit
    }
}

struct TokenBucket {
    let capacity: Double, refillPerSecond: Double
    private var tokens: Double, last: Double
    init(capacity: Double, refillPerSecond: Double, now: Double) {
        self.capacity = capacity; self.refillPerSecond = refillPerSecond
        tokens = capacity; last = now
    }
    mutating func allow(now: Double) -> Bool {
        tokens = min(capacity, tokens + (now - last) * refillPerSecond)
        last = now
        guard tokens >= 1 else { return false }
        tokens -= 1
        return true
    }
}

struct RingBuffer<T> {
    private var slots: [T?], head = 0, count = 0
    init(capacity: Int) { slots = Array(repeating: nil, count: max(1, capacity)) }
    mutating func write(_ x: T) {                        // overwrites the oldest when full
        slots[(head + count) % slots.count] = x
        if count == slots.count { head = (head + 1) % slots.count } else { count += 1 }
    }
    mutating func read() -> T? {
        guard count > 0 else { return nil }
        defer { slots[head] = nil; head = (head + 1) % slots.count; count -= 1 }
        return slots[head]
    }
}
